syntax:
// Same idea at different levels (the first two lines are examples, not C++)
// Machine language : 10110000 01100001      (binary, hard for humans)
// Assembly         : MOV AL, 61h            (short code, still hard)
// C++ (middle)     : int sum = a + 3;       (readable)
//                    cout << sum;
// Python (high)    : print(a + 3)           (even shorter)

sample.code:
#include <iostream>
using namespace std;

int main() {
    int a = 5;
    int b = 3;
    int sum = a + b;
    cout << "Sum = " << sum << endl;
    return 0;
}

#include <iostream>
using namespace std;

